import {DODGE_TIMING,PRACTICE_KINDS,trainingMission,checkpointTraining,GROUNDS,STATS,ITEMS,SKILLS,ENEMIES,readSave,writeSave,xpNeeded,combatStats,trainingCost,buyItem,upgradeGround,learnSkill,allocateStat,settleTraining,settleBattle,legacyCost,passiveCoins,collectMuseum,upgradeLegacy,purchasePotion} from './core.js';
import {drawWorld,hero,enemy} from './art.js';
import {Training} from './training.js';
import {placeStrengthControls} from './strength-layout.js';
import {Battle} from './battle.js';
import {setupMobile} from './mobile.js';
const $=s=>document.querySelector(s),screen=$('#screen'),canvas=$('#world'),ctx=canvas.getContext('2d'),dialog=$('#dialog');
let storage;try{storage=window.localStorage}catch{storage={getItem(){throw Error('Storage unavailable')},setItem(){throw Error('Storage unavailable')}}}
const loaded=readSave(storage);let player=loaded.player,view='town',selectedStage=Math.min(player.stage,12),session=null,paused=false,lastTime=0,toastTimer=0,audio=null,saveWarning=false,returnFocus=null;
const mobile=setupMobile(()=>{const status=$('#offline-status');if(status)status.textContent=mobile.status;const update=$('#install-update');if(update)update.hidden=!mobile.updateReady});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>Math.round(n*100)+'%';
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function save(){const ok=writeSave(storage,player);if(!ok&&!saveWarning){saveWarning=true;toast('Saving is unavailable in this browser. Keep this tab open.')}$('#coins').textContent=player.coins.toLocaleString();return ok}
function sound(kind){if(!player.settings.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';const f=({hit:640,heal:440,block:360,star:880,miss:160})[kind]||640;osc.frequency.setValueAtTime(f,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(kind==='miss'?65:kind==='block'?210:f*1.5,audio.currentTime+.09);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.13)}catch{}}
function modal(html){dialog.classList.toggle('strength-dialog',session?.streak);returnFocus=document.activeElement;dialog.innerHTML=html;if(!dialog.open)dialog.showModal()}
function closeModal(){dialog.close();returnFocus?.focus?.();if(session&&!session.done)paused=document.hidden||window.innerHeight>window.innerWidth}
function header(title){$('#location').textContent=title;$('#coins').textContent=player.coins.toLocaleString();const active={training:'train',battle:'arena'}[view]||view;$('#nav').innerHTML=[['town','⌂','Town'],['train','◎','Train'],['arena','⚔','Arena'],['forge','⚒','Forge'],['hero','♙','Hero'],['legacy','✦','Legacy']].map(([id,icon,label])=>`<button data-go="${id}" class="${id===active?'active':''}" ${id===active?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}
function page(title,kicker,body,subtitle=''){screen.innerHTML=`<section class="page"><div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="back" data-go="town">← Town</button></div>${body}</section>`}
function town(){header('Skyhaven');screen.innerHTML=`<div class="town-intro"><span class="eyebrow">THE SKYBOUND ISLES · CHAPTER ONE</span><h1>Welcome to Skyhaven.</h1><p>A little training. A little courage. A world to discover.</p></div><div class="daily-note"><b>${player.cleared.length?'Your legend is taking shape.':'Start small. Grow extraordinary.'}</b>${player.cleared.length?player.cleared.length+' / 12 arena encounters cleared':'Visit the training grounds to find your footing.'}</div><button data-go="train" class="map-pin featured" style="left:51%;top:60%"><b>◎ Training grounds</b><small>Five ways to grow stronger</small></button><button data-go="arena" class="map-pin" style="left:62%;top:26%"><b>⚔ The Cloudring</b><small>${player.stage>12?'Survival unlocked':'Arena · Encounter '+player.stage}</small></button><button data-go="forge" class="map-pin" style="left:77%;top:63%"><b>⚒ The Skyforge</b><small>Weapons & armor</small></button><button data-go="legacy" class="map-pin" style="left:39%;top:43%"><b>⌂ Windward Lodge</b><small>Build your legacy</small></button><button class="hero-card" data-go="hero" style="text-align:left"><span class="eyebrow">YOUR ADVENTURER</span><h3>${escape(player.name)} <span class="pill">Lv. ${player.level}</span></h3><p>${player.statPoints?player.statPoints+' stat points ready to spend':'Every legend starts somewhere.'}</p><div class="track"><i style="width:${pct(player.xp/xpNeeded(player))}"></i></div><div class="stat-line"><span>${player.xp} / ${xpNeeded(player)} XP</span><span>View hero ›</span></div></button>`}
function trainMenu(){header('Training grounds');page('A little better, every day.','TRAINING GROUNDS',`<div class="cards">${GROUNDS.map(g=>`<article class="card" style="--accent:${g.color}"><div class="row spread"><span class="pill">Lv. ${player.trainingLevels[g.id]} grounds</span><span class="sub">${(1+.25*(player.trainingLevels[g.id]-1)).toFixed(2)}×</span></div><div class="sigil" aria-hidden="true">${g.icon}</div><h2>${g.name}</h2><div class="row spread"><b class="value">${player.stats[g.id]}</b><span class="sub">${g.benefit}</span></div><p>${g.description}</p><button class="primary" data-train="${g.id}">${PRACTICE_KINDS.includes(g.id)?'Train':'Train · 30s'}</button><button class="secondary" data-upgrade="${g.id}" ${player.trainingLevels[g.id]>=5?'disabled':''}>${player.trainingLevels[g.id]>=5?'Fully upgraded':'Upgrade · ◆ '+trainingCost(player,g.id)}</button></article>`).join('')}</div>`,'Earn stats and XP. Strength, Dodge, Block and Critical goals raise stats. Upgrades speed up their goal progress.')}
function arenaMenu(){header('The Cloudring');page('Courage meets its match.','THE CLOUDRING',`<div class="arena-levels">${ENEMIES.map((n,i)=>`<button data-stage="${i+1}" aria-label="Encounter ${i+1}: ${n}${i+1>player.stage?', locked':''}" class="${selectedStage===i+1?'selected ':''}${player.cleared.includes(i+1)?'cleared':''}" ${i+1>player.stage?'disabled':''}>${i+1>player.stage?'◇':i+1}</button>`).join('')}</div><article class="card battle-card"><canvas class="enemy-preview" width="400" height="180" data-enemy="${(selectedStage-1)%3}" aria-label="Encounter enemy"></canvas><span class="eyebrow">ENCOUNTER ${selectedStage} · THREE WAVES</span><h2>${ENEMIES[selectedStage-1]}</h2><p>${player.cleared.includes(selectedStage)?'Return for more coins and experience. Repeat clears pay 65%.':'Win every wave to unlock the next encounter and earn a skill point.'}</p><div class="row" style="justify-content:center"><span class="pill">◆ ${Math.round((30+selectedStage*18)*(1+player.home*.1)*(player.cleared.includes(selectedStage)?.65:1))} coins</span><span class="pill">✦ ${25+selectedStage*8} XP</span></div><div class="row"><button class="primary" data-fight="${selectedStage}" style="flex:1">Enter the arena ⚔</button>${player.stage>12?'<button class="secondary" data-survival="true">Endless survival</button>':''}</div></article>`)}
function forge(){header('The Skyforge');const stats=combatStats(player);page('Made for the road ahead.','THE SKYFORGE',`<div class="two-col"><div class="portrait"><canvas data-hero width="400" height="340" aria-label="Your hero wearing equipped weapon and armor"></canvas><h2>${escape(player.name)}</h2><div class="row"><span class="pill">⚔ ${stats.attack} attack</span><span class="pill">♥ ${stats.hp} HP</span></div><p>Equipment changes your appearance.</p></div><div class="shop-grid">${['weapon','armor'].map(slot=>`<article class="card"><span class="eyebrow">${slot==='weapon'?'⚔ WEAPON':'⬡ ARMOR'}</span>${Object.values(ITEMS).filter(i=>i.slot===slot).map(i=>`<div class="stat-row"><div><b>${i.name}</b><p>${slot==='weapon'?'+'+i.bonus+' attack':'+'+i.bonus+' health'}</p></div><button class="${player.equipment[slot]===i.id?'secondary':'primary'}" data-item="${i.id}" ${player.equipment[slot]===i.id?'disabled':''} style="margin-left:auto;min-width:76px;font-size:12px">${player.equipment[slot]===i.id?'Equipped':player.inventory.includes(i.id)?'Equip':'◆ '+i.cost}</button></div>`).join('')}</article>`).join('')}<article class="card" style="grid-column:1/-1"><div class="row spread"><div><b>Skyberry tonic</b><p>Restore 45% HP in battle. In pouch: ${player.potions} / 9</p></div><button class="primary" data-action="tonic-buy">Buy · ◆ 25</button></div></article></div></div>`)}
function heroMenu(){header('Your adventurer');const s=combatStats(player);page('A legend in the making.','YOUR HERO',`<div class="two-col"><div class="portrait"><canvas data-hero width="400" height="340" aria-label="Your adventurer"></canvas><h2>${escape(player.name)} <span class="pill">Level ${player.level}</span></h2><button class="secondary" data-action="appearance">Name & scarf</button><div class="track" style="width:100%"><i style="width:${pct(player.xp/xpNeeded(player))}"></i></div><p>${player.xp} / ${xpNeeded(player)} XP · ${player.statPoints} stat points</p></div><div><div class="row" style="margin-bottom:8px"><span class="pill">⚔ ${s.attack} attack</span><span class="pill">♥ ${s.hp} HP</span><span class="pill">${player.skillPoints} skill points</span></div>${GROUNDS.map(g=>`<div class="stat-row"><span style="color:${g.color};width:25px">${g.icon}</span><span>${g.name}</span><span class="sub" style="color:var(--muted);font-size:12px">${g.id==='strength'?s.attack+' damage':g.id==='accuracy'?pct(s.hit)+' hit chance':g.id==='dodge'?pct(s.dodge)+' evade':g.id==='block'?pct(s.block)+' block chance':pct(s.crit)+' crit chance'}</span><b>${player.stats[g.id]}</b><button data-stat="${g.id}" aria-label="Increase ${g.name}" ${player.statPoints<1?'disabled':''}>+</button></div>`).join('')}</div></div><div class="skill-list">${Object.entries(SKILLS).map(([k,s])=>`<article class="card"><h2>${s.icon} ${s.name}</h2><p>${s.description}</p><button class="${player.skills.includes(k)?'secondary':'primary'}" data-skill="${k}" ${player.skills.includes(k)?'disabled':''}>${player.skills.includes(k)?'Learned':s.cost+' skill point'+(s.cost===1?'':'s')}</button></article>`).join('')}</div>`)}
function legacy(){header('Windward Lodge');page('A place worth coming home to.','YOUR LEGACY',`<div class="skill-list"><article class="card"><div class="sigil">⌂</div><h2>Windward Lodge</h2><span class="pill">Level ${player.home} / 5</span><p>A home above the clouds. Each improvement adds 10% to arena coin rewards.</p><b>Current bonus: +${player.home*10}% coins</b><button class="primary" data-legacy="home" ${player.home>=5?'disabled':''}>${player.home>=5?'Fully built':'Build · ◆ '+legacyCost(player,'home')}</button></article><article class="card"><div class="sigil">✦</div><h2>Cloudkeeper Gallery</h2><span class="pill">Level ${player.museum} / 5</span><p>Each arena trophy earns ${player.museum} coin${player.museum===1?'':'s'} per minute. Income accumulates for up to 8 hours.</p><b>${player.cleared.length} trophies · <span id="passive">${passiveCoins(player)}</span> coins waiting</b><button class="primary" data-action="collect">Collect coins</button><button class="secondary" data-legacy="museum" ${player.museum>=5?'disabled':''}>${player.museum>=5?'Fully built':'Expand · ◆ '+legacyCost(player,'museum')}</button></article><article class="card"><div class="sigil">◇</div><h2>Adventure journal</h2><p>Your first chapter, one small victory at a time.</p><div class="stat-row"><span>Arena encounters</span><b>${player.cleared.length} / 12</b></div><div class="stat-row"><span>Training sessions</span><b>${player.sessions}</b></div><div class="stat-row"><span>Successful hits</span><b>${player.totalHits}</b></div><div class="stat-row"><span>Best combo</span><b>${player.bestCombo}</b></div></article></div>`)}
function navigate(target,force=false){if(!['town','train','arena','forge','hero','legacy'].includes(target))return false;if(session&&!session.done&&!force){if(view==='training'&&target==='town')trainingResult();else pauseMenu(target);return false}session=null;paused=false;$('#app').classList.remove('strength-session','block-session','critical-session');screen.classList.remove('training-run');view=target;({town,train:trainMenu,arena:arenaMenu,forge,hero:heroMenu,legacy})[target]();return true}
function startTraining(kind){if(!STATS.includes(kind)||session&&!session.done)return;view='training';session=new Training(kind,player,sound);session.reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;screen.classList.add('training-run');paused=false;if(session.streak){practiceScreen();updateHud();return}const g=GROUNDS.find(g=>g.id===kind);header(g.name+' training');const instructions={accuracy:'Tap Throw when the sight overlaps the target.'};const buttons=`<span></span><button class="control gold wide" data-input="tap">${{accuracy:'◎ Throw'}[kind]}</button>`;screen.innerHTML=`<div class="training-hud"><div><span class="eyebrow" style="color:#326674">TRAINING GROUNDS</span><h2>${g.name}</h2></div><div class="row"><div class="metric"><b id="time">30</b><small>seconds left</small></div><div class="metric"><b id="hits">0</b><small>good hits</small></div><div class="metric"><b id="combo">0×</b><small>combo</small></div><button class="back" data-action="pause">Ⅱ Pause</button></div></div><div class="instruction">${instructions[kind]}</div><div class="controls">${buttons}</div>`;updateHud()}
function practiceScreen(){
$('#app').classList.add('strength-session');
const dodge=session.kind==='dodge',block=session.kind==='block',critical=session.kind==='crit',name=GROUNDS.find(g=>g.id===session.kind).name;
$('#app').classList.toggle('block-session',block);$('#app').classList.toggle('critical-session',critical);
header(name+' training');
const tutorial=session.tutorialRemaining>0;
if(tutorial){player.tutorials[session.kind]=true;save()}
const controls=block||critical?[]:dodge?[['high','jump','Jump'],['low','tuck','Tuck'],['kick','back','Back']]:[['high','0','High'],['low','2','Low'],['mid','1','Mid']];
const instructions=critical?'Tap only on HIT! Wait for the second cue. Mistakes reset your combo.':block?'Drag to aim the shield. Block oranges. Let stars through to collect them.':dodge?'Tuck: high. Jump: low. Back: mid. Dodge just before impact for a star.':'High, Mid or Low to slash fruit. Kick for stars. Town banks your rewards.';
screen.innerHTML=`${critical?'<button id="critical-playfield" data-input="hit" aria-label="Critical training play area. Tap only on HIT to jump. Wait for the airborne HIT, then tap for a star. Missed cues or taps without HIT reset the combo."></button>':''}${controls.map(([key,action,label])=>`<button class="strength-action ${key==='kick'?'kick-action':''}" data-layout="${key}" data-input="${action}" aria-label="${label}${dodge?' dodge':' slash'}">${label}</button>`).join('')}<div class="strength-hud"><button class="strength-town" data-go="town" aria-label="Finish practice and show results">← Town</button><div class="training-goal"><span class="goal-track"><span class="goal-well" aria-hidden="true"><i id="goal-fill"></i></span><span class="goal-marker" aria-hidden="true"></span><progress class="sr-only" id="goal-meter" max="4" value="0" aria-label="Points toward the next stat increase"></progress></span><b id="combo" aria-label="Combo multiplier">×1</b></div></div>${dodge||block||critical?'':'<button class="strength-action kick-action" data-layout="kick" data-input="kick" aria-label="Rear kick — strike falling sparks">Kick</button>'}${block?'<div id="block-stick" role="slider" tabindex="0" aria-label="Rotate shield" aria-valuemin="0" aria-valuemax="359" aria-valuenow="0"><span class="block-stick-knob"></span></div>':''}${critical?'<span id="critical-cue-status" class="sr-only" role="status"></span>':''}<aside class="training-mission strength-goal" aria-label="Side mission"><div class="goal-caption"><b id="mission-number"></b><span id="mission-progress"></span></div><div id="mission-title"></div><progress id="mission-meter" max="1" value="0" aria-label="Side mission progress"></progress><span id="mission-message" role="status"></span></aside>${tutorial?`<div id="strength-tutorial" class="strength-tutorial" role="status">${instructions}</div>`:''}<div id="goal-announcement" class="sr-only" role="status"></div>`;placeStrengthControls(screen);if(block)bindBlockStick()
}
function bindBlockStick(){
const pad=$('#block-stick');let pointer=null;
const active=()=>session?.kind==='block'&&!session.done&&!paused;
const aim=angle=>{session.aimShield(angle);const degrees=Math.round((angle*180/Math.PI+360)%360)%360;pad.setAttribute('aria-valuenow',degrees);pad.setAttribute('aria-valuetext',degrees+' degrees')};
const move=e=>{
if(!active())return;
const r=pad.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,distance=Math.hypot(dx,dy),limit=r.width/2-23,scale=Math.min(1,limit/Math.max(1,distance));
pad.style.setProperty('--stick-x',dx*scale+'px');pad.style.setProperty('--stick-y',dy*scale+'px');
if(distance>=7){const field=canvas.getBoundingClientRect();aim(Math.atan2(dy*700/field.height,dx*1400/field.width))}
};
const release=()=>{const id=pointer;pointer=null;delete pad.dataset.engaged;pad.style.setProperty('--stick-x','0px');pad.style.setProperty('--stick-y','0px');if(id!==null&&pad.hasPointerCapture(id))pad.releasePointerCapture(id)};
pad.addEventListener('pointerdown',e=>{if(e.button!==0||pointer!==null||!active())return;e.preventDefault();pointer=e.pointerId;pad.dataset.engaged='true';pad.setPointerCapture(pointer);pad.focus({preventScroll:true});move(e)});
pad.addEventListener('pointermove',e=>{if(e.pointerId===pointer){e.preventDefault();move(e)}});
for(const event of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(event,e=>{if(e.pointerId===pointer)release()});
pad.addEventListener('blur',release);
pad.addEventListener('keydown',e=>{if(!active())return;const directions={ArrowRight:0,ArrowDown:Math.PI/2,ArrowLeft:Math.PI,ArrowUp:-Math.PI/2};if(e.key in directions){e.preventDefault();aim(directions[e.key])}})
}
function trainingResult(){
const result=settleTraining(player,session);
if(!result)return;
save();
const kind=session.kind,name=GROUNDS.find(g=>g.id===kind).name;
modal(`<div class="training-rewards"><div class="reward">+${result.gain} ${name}</div><p class="training-xp">+${result.xp} XP</p><div class="row"><button class="secondary" data-finish="town">Back to Town</button><button class="primary" data-retry="${kind}">Train again</button></div></div>`)
}
function startBattle(stage,survival=false){if(!Number.isInteger(stage)||stage<1||stage>12||stage>player.stage||session&&!session.done)return;if(survival&&player.stage<=12)return;view='battle';session=new Battle(player,stage,sound,survival);paused=false;header(survival?'Endless survival':'The Cloudring');screen.innerHTML=`<div class="battle-hud"><div class="health"><h3>${escape(player.name)}</h3><div class="track"><i id="hero-health" style="width:100%"></i></div><small id="hero-hp"></small></div><div class="health"><h3 id="enemy-name"></h3><div class="track"><i id="enemy-health" style="width:100%"></i></div><small id="enemy-hp"></small></div></div><div class="battle-message" id="battle-message"></div><button class="event" id="event" data-input="event" hidden>✦<br>STRIKE!</button><div class="controls"><button class="control" data-action="pause">Ⅱ Pause</button><div class="cluster">${Object.entries(SKILLS).map(([k,s])=>`<button class="control" data-input="${k}" id="skill-${k}" ${player.skills.includes(k)?'':'disabled'}>${s.icon} ${s.name}<em>${player.skills.includes(k)?'Ready':'Learn in Hero'}</em></button>`).join('')}<button class="control gold" data-input="tonic" id="skill-tonic">❋ Tonic<em>${player.potions} left</em></button></div></div>`}
function battleResult(retreated=false){const b=session;const result=settleBattle(player,b,b.won);if(!result)return;b.done=true;save();selectedStage=Math.min(player.stage,12);modal(`<span class="eyebrow">${b.survival?'SURVIVAL · '+b.wavesCleared+' WAVES':b.won?'ENCOUNTER CLEARED':'THE CLOUDRING'}</span><h2>${b.won?'A well-earned victory.':retreated?'Live to fight another day.':'A lesson, not the end.'}</h2><div class="reward">${result.coins?'◆ +'+result.coins:'Train. Return. Conquer.'}</div><p style="text-align:center">${result.xp?'+'+result.xp+' XP':''}${result.first?' · +1 skill point':''}${result.levels?' · Level up!':''}</p><p>${b.won?player.stage>12?'Chapter one complete! Endless survival is now open.':'New encounters await. Visit the forge or keep training.':'Your progression is safe. Train your stats or upgrade your equipment before trying again.'}</p><div class="row"><button class="secondary" data-finish="train">Training grounds</button><button class="primary" data-finish="arena">Back to arena</button></div>`)}
function pauseMenu(destination='town'){if(!session||session.done)return;paused=true;modal(`<span class="eyebrow">TAKE A BREATHER</span><h2>Adventure paused.</h2><p>${view==='training'?(session.streak?'Your earned stats, XP and completed goal bonuses will be banked when you leave.':'Your good hits will be banked when you leave.'):'You can resume here. Retreating ends this fight; survival rewards already earned are kept.'}</p><div class="row"><button class="secondary" data-leave="${destination}">${view==='training'?'Bank & leave':'Retreat'}</button><button class="primary" data-action="resume">Resume</button></div>`)}
function settings(){if(session&&!session.done)paused=true;modal(`<span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>Settings</h2><button class="secondary" style="width:100%;margin:6px 0" data-action="sound" aria-pressed="${player.settings.sound}">Sound effects: ${player.settings.sound?'On':'Off'}</button><button class="secondary" style="width:100%;margin:6px 0" data-action="motion" aria-pressed="${player.settings.motion}">Extra motion: ${player.settings.motion?'On':'Off'}</button><p id="offline-status" role="status">${mobile.status}</p><button id="install-update" class="secondary" style="width:100%;margin:6px 0" data-action="app-update" ${mobile.updateReady?'':'hidden'} ${session&&!session.done?'disabled':''}>${session&&!session.done?'Finish your run to update':'Install game update'}</button><p>Progress saves on this browser and device. ${saveWarning?'Saving is currently unavailable.':'Rewards and purchases are saved automatically.'}</p><button class="primary" style="width:100%" data-action="close">Back to adventure</button>`)}
function appearance(){modal(`<span class="eyebrow">YOUR ADVENTURER</span><h2>A name for your journey.</h2><label for="hero-name">Hero name</label><input id="hero-name" maxlength="18" value="${escape(player.name)}" autocomplete="off"><label>Scarf color</label><div class="row">${[['#63dbc4','Sea glass'],['#f0ad65','Sunrise'],['#b89be0','Dusk']].map(([color,label])=>`<button class="secondary" data-scarf="${color}" style="border-color:${color};color:${color}" aria-pressed="${player.scarf===color}">${label}${player.scarf===color?' ✓':''}</button>`).join('')}</div><div class="row"><button class="primary" data-action="name-save">Save appearance</button></div>`)}
function act(el){if(el.disabled)return;const d=el.dataset;if(d.go){navigate(d.go);return}if(d.train){startTraining(d.train);return}if(d.stage){selectedStage=Number(d.stage);arenaMenu();return}if(d.fight){startBattle(Number(d.fight));return}if(d.survival){startBattle(12,true);return}if(d.input){if(session&&!paused){const changed=session.input(d.input);if(view==='battle'&&changed&&d.input==='tonic')save()}return}if(d.finish){closeModal();navigate(d.finish,true);return}if(d.retry){closeModal();session=null;startTraining(d.retry);return}if(d.leave){closeModal();if(view==='training')trainingResult();else battleResult(true);return}if(d.scarf){const name=$('#hero-name').value;player.scarf=d.scarf;appearance();$('#hero-name').value=name;return}let result;if(d.item)result=buyItem(player,d.item);if(d.upgrade)result=upgradeGround(player,d.upgrade);if(d.skill)result=learnSkill(player,d.skill);if(d.legacy)result=upgradeLegacy(player,d.legacy);if(d.stat){if(allocateStat(player,d.stat)){save();heroMenu()}return}if(result){if(result.ok){save();navigate(view,true);sound('heal')}toast(result.message);return}switch(d.action){case'app-update':if(!session||session.done){save();mobile.applyUpdate().then(message=>{if(message)toast(message)})}break;case'pause':pauseMenu();break;case'resume':case'close':closeModal();break;case'sound':player.settings.sound=!player.settings.sound;save();sound('heal');settings();break;case'motion':player.settings.motion=!player.settings.motion;save();settings();break;case'appearance':appearance();break;case'name-save':player.name=$('#hero-name').value.trim().slice(0,18)||'Rook';save();closeModal();heroMenu();break;case'tonic-buy':result=purchasePotion(player);if(result.ok){save();forge()}toast(result.message);break;case'collect':{const amount=collectMuseum(player);save();legacy();toast(amount?'Collected '+amount+' coins.':player.museum?'Your gallery is still earning. Check back soon.':'Build the gallery and clear an arena encounter to earn income.');break}}}
document.addEventListener('pointerdown',e=>{const button=e.target.closest('button');if(!button||e.button!==0||button.id==='critical-playfield'&&e.isPrimary===false)return;e.preventDefault();if(button.id==='critical-playfield')button.dataset.pointerFocus='';button.focus({preventScroll:true});if(button.id==='settings')settings();else act(button)});
document.addEventListener('click',e=>{if(e.detail!==0)return;const button=e.target.closest('button');if(!button)return;if(button.id==='settings')settings();else act(button)});
document.addEventListener('keydown',e=>{const field=$('#critical-playfield');if(field)delete field.dataset.pointerFocus;if(e.target===field&&e.repeat&&(e.key==='Enter'||e.key===' '))e.preventDefault()});
document.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('gesturestart',e=>e.preventDefault(),{passive:false});document.addEventListener('touchstart',e=>{if(e.touches.length>1)e.preventDefault()},{passive:false});
dialog.addEventListener('cancel',e=>{e.preventDefault();if(session?.done){closeModal();navigate(view==='training'?'train':'arena',true)}else closeModal()});
function syncViewport(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||window.innerHeight)+'px');if(session?.streak)placeStrengthControls(screen);if(window.innerHeight>window.innerWidth&&session&&!session.done&&!paused)pauseMenu()}
window.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('resize',syncViewport);document.addEventListener('visibilitychange',()=>{if(document.hidden&&session&&!session.done&&!paused)pauseMenu();if(session?.streak&&!session.rewarded){checkpointTraining(player,session);save()}lastTime=0});window.addEventListener('pagehide',()=>{if(view==='training'&&session&&!session.rewarded)settleTraining(player,session);if(view==='battle'&&session?.survival&&!session.rewarded)settleBattle(player,session,false);save()});window.addEventListener('pageshow',e=>{if(e.persisted){player=readSave(storage).player;if(dialog.open)dialog.close();navigate('town',true)}});
function setText(id,value){const el=document.getElementById(id);if(el&&el.textContent!==String(value))el.textContent=value}
function updateHud(){if(view==='training'){for(const [part,delay] of [['goal',0],['mission',.2],['controls',.35]])screen.style.setProperty('--intro-'+part,session.entrance(delay));setText('time',Math.ceil(30-session.elapsed));setText('hits',session.hits);setText('combo',session.streak?'×'+session.combo:session.combo+'×');if(session.kind==='crit')setText('critical-cue-status',session.criticalRound?.phase==='fake'?'Fake cue. Wait.':['ready','finish'].includes(session.criticalRound?.phase)?'Hit now.':'');const combo=$('#combo'),cue=session.comboFeedback>0;combo.style.setProperty('--combo-scale',session.motion?1+(session.comboStar?.35:.22)*Math.sin(Math.PI*(1-session.comboFeedback/.42)):1);combo.classList.toggle('combo-success',cue);combo.classList.toggle('combo-star',cue&&session.comboStar);if(session.streak){const meter=$('#goal-meter');if(meter.max!==session.goalTarget)meter.max=session.goalTarget;if(meter.value!==session.goalProgress)meter.value=session.goalProgress;const track=meter.closest('.goal-track'),fillWidth=(session.goalFeedback>1.56?100:Math.max(0,Math.min(100,session.goalProgress/session.goalTarget*100)))+'%';if(track.style.getPropertyValue('--goal-progress')!==fillWidth)track.style.setProperty('--goal-progress',fillWidth);meter.setAttribute('aria-valuetext',Number(session.goalProgress.toFixed(2))+' of '+session.goalTarget+' points');meter.closest('.training-goal').classList.toggle('goal-banked',session.goalFeedback>0);if(session.goals)setText('goal-announcement',session.goals+' goals banked. Next goal: '+session.goalTarget+' points.');const mission=trainingMission(session.kind,session.missionNumber);setText('mission-number','Mission #'+mission.number);setText('mission-title',mission.title);setText('mission-progress',(mission.type==='unhurt'?session.missionProgress.toFixed(1):session.missionProgress)+' / '+mission.target);const missionMeter=$('#mission-meter');missionMeter.max=mission.target;missionMeter.value=session.missionProgress;missionMeter.parentElement.classList.toggle('goal-banked',session.missionFeedback>0);setText('mission-message',session.missionFeedback>0?session.missionMessage:'');const tutorial=$('#strength-tutorial');if(tutorial){if(session.tutorialRemaining<=0)tutorial.remove();else tutorial.style.opacity=Math.min(1,session.tutorialRemaining/.5)}}if(session.kind==='dodge')document.querySelectorAll('[data-input]').forEach(b=>b.classList.toggle('gold',b.dataset.input===session.action&&session.elapsed-session.dodgeAt<DODGE_TIMING.window))}else if(view==='battle'){const b=session;$('#hero-health').style.width=pct(b.hp/b.stats.hp);$('#enemy-health').style.width=pct(b.enemyHp/b.foe.hp);setText('hero-hp',b.hp+' / '+b.stats.hp+' HP');setText('enemy-hp',b.enemyHp+' / '+b.foe.hp+' HP · Wave '+(b.wave+1)+(b.survival?'':' / 3'));setText('enemy-name',b.foe.name);setText('battle-message',b.message);$('#event').hidden=b.event<=0||b.done;for(const k of ['flare','ward','mend','tonic']){const el=$('#skill-'+k);const learned=k==='tonic'?player.potions>0:player.skills.includes(k);el.disabled=!learned||b.cooldowns[k]>0||((k==='mend'||k==='tonic')&&b.hp>=b.stats.hp);el.querySelector('em').textContent=!learned?(k==='tonic'?'Empty pouch':'Learn in Hero'):b.cooldowns[k]>0?Math.ceil(b.cooldowns[k])+'s':k==='tonic'?player.potions+' left':'Ready'}}}
function drawPortraits(t){document.querySelectorAll('canvas[data-hero]').forEach(c=>{const q=c.getContext('2d');q.clearRect(0,0,c.width,c.height);hero(q,c.width/2,c.height-15,1.8,player.equipment,t,0,0,player.scarf)});document.querySelectorAll('canvas[data-enemy]').forEach(c=>{const q=c.getContext('2d');q.clearRect(0,0,c.width,c.height);enemy(q,c.width/2,c.height-15,1.3,Number(c.dataset.enemy),t)})}
function frame(timestamp){requestAnimationFrame(frame);const dt=lastTime?Math.min((timestamp-lastTime)/1000,.05):0;lastTime=timestamp;if(session?.savePending){checkpointTraining(player,session);save()}if(document.hidden)return;if(session&&!paused&&!session.done&&window.innerWidth>=window.innerHeight){session.step(dt);if(session.done){if(view==='training')trainingResult();else battleResult()}}const r=canvas.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,2);if(!r.width||!r.height)return;if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}ctx.setTransform(d,0,0,d,0,0);const t=player.settings.motion?timestamp/1000:0;drawWorld(ctx,r.width,r.height,t,view==='town'?'town':view==='battle'?'battle':'training');if(session){ctx.save();ctx.scale(r.width/1400,r.height/700);if((view==='training'?session.motion:player.settings.motion)&&!paused&&session.hit&&session.kind!=='block')ctx.translate(Math.sin(timestamp*.08)*session.hit*5,0);session.draw(ctx,view==='training'?(session.motion?session.elapsed:0):paused?0:t);ctx.restore();updateHud()}drawPortraits(t);if(view==='legacy')setText('passive',passiveCoins(player))}
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const tools=[{name:'read_adventure',title:'Read adventure progress',description:'Read this device’s saved hero progression and current game screen.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments accepted.');return{screen:view,hero:player.name,level:player.level,coins:player.coins,stats:{...player.stats},equipment:{...player.equipment},cleared:[...player.cleared],skillPoints:player.skillPoints,statPoints:player.statPoints}}},{name:'navigate_adventure',title:'Open game destination',description:'Navigate to a town destination. Does not play, buy, spend points or grant rewards. Refuses during an active round.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['town','train','arena','forge','hero','legacy']}},required:['destination'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['town','train','arena','forge','hero','legacy'].includes(input.destination))throw Error('Invalid destination.');if(session&&!session.done||dialog.open)throw Error('Finish the active round or dialog first.');navigate(input.destination);return{screen:view}}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
syncViewport();navigate('town');if(loaded.warning)toast(loaded.warning);requestAnimationFrame(frame);registerAgentTools();
